def _object_code_root_second_export_named_dependency_single_helper_case(
    dummy_count: int = 35,
    *,
    library_dependency: bool = False,
    library_helper: bool = False,
) -> dict[str, object]:
    dummy_names = [f"d{i}" for i in range(dummy_count)]
    helper_object = (
        "OBJ1\n"
        "x a 0 4\n"
        "b M\n"
        + "".join(f"u {name}\n" for name in dummy_names)
        + "m 20 00 00 60\n"
        "r 1 x helper\n"
        "n a\n"
    )
    extra_objects = {
        f"{name.upper()}.OBJ": f"OBJ1\nx {name} 0 1\nb M\nm EA\nn {name}\n"
        for name in dummy_names
    }
    extra_library_objects = {
        f"{name.upper()}.OBJ": f"OBJ1\nx {name} 0 1\nb M\nm EA\nn {name}\n"
        for name in dummy_names
    }
    if library_dependency:
        extra_library_objects["A.OBJ"] = helper_object
    else:
        extra_objects["A.OBJ"] = helper_object
        extra_library_objects["A.OBJ"] = "OBJ1\nx a 0 1\nb M\nm EA\nn a\n"
    if library_helper:
        extra_library_objects["HELPER.OBJ"] = "OBJ1\nx helper 0 1\nb M\nm 60\nn helper\n"
    else:
        extra_objects["HELPER.OBJ"] = "OBJ1\nx helper 0 1\nb M\nm 60\nn helper\n"
        extra_library_objects["HELPER.OBJ"] = "OBJ1\nx helper 0 1\nb M\nm EA\nn helper\n"
    expected_loads = [
        "LIB/A.OBJ" if library_dependency else "OBJ/A.OBJ",
        "LIB/HELPER.OBJ" if library_helper else "OBJ/HELPER.OBJ",
    ]
    unexpected_loads = [
        "OBJ/A.OBJ" if library_dependency else "LIB/A.OBJ",
        "OBJ/HELPER.OBJ" if library_helper else "LIB/HELPER.OBJ",
        *[f"OBJ/{name.upper()}.OBJ" for name in dummy_names],
        *[f"LIB/{name.upper()}.OBJ" for name in dummy_names],
    ]
    return {
        "seed_object": (
            "OBJ1\n"
            "x unused 0 1\n"
            "x main 1 19\n"
            "b M\n"
            "b u0M\n"
            "u a\n"
            "m EA 20 00 00 A9 A5 8D D0 03 A9 00 85 02 85 03 A2 02 4C 0F CF\n"
            "r 2 u0\n"
            "n main\n"
        ),
        "has_stub": False,
        "extra_objects": extra_objects,
        "extra_library_objects": extra_library_objects,
        "expected_tail": bytes.fromhex("201310A9A58DD003A90085028503A2024C0FCF2017106060"),
        "expected_alink_loads": expected_loads,
        "unexpected_alink_loads": unexpected_loads,
    }


