def _object_code_named_large_dependency_page_crossing_case(
    *,
    project_dependency: bool = False,
    project_tail: bool = False,
    root_second_export: bool = False,
) -> dict[str, object]:
    root = bytearray(bytes.fromhex("20 00 00") + _DIRECT_PRG_EXIT_MARKER)
    large_size = 272
    a_addr = DIRECT_PRG_LOAD_ADDR + len(root)
    b_addr = a_addr + large_size
    root[1] = a_addr & 0xFF
    root[2] = a_addr >> 8
    a_seed = bytearray([0x20, 0x00, 0x00])
    a_seed.extend([0xEA] * (large_size - len(a_seed) - 1))
    a_seed.append(0x60)
    a_expected = bytearray(a_seed)
    a_expected[1] = b_addr & 0xFF
    a_expected[2] = b_addr >> 8
    seed_object = (
        "OBJ1\n"
        "x main 0 19\n"
        "b u0M\n"
        "u a\n"
        "m 20 00 00 A9 A5 8D D0 03 A9 00 85 02 85 03 A2 02 4C 0F CF\n"
        "r 1 u0\n"
        "n main\n"
    )
    if root_second_export:
        seed_object = (
            "OBJ1\n"
            "x unused 0 1\n"
            "x main 1 19\n"
            "b M\n"
            "b u0M\n"
            "u a\n"
            "m EA 20 00 00 A9 A5 8D D0 03 A9 00 85 02 85 03 A2 02 4C 0F CF\n"
            "r 2 u0\n"
            "n main\n"
        )
    a_object = (
        "OBJ1\n"
        f"x a 0 {large_size}\n"
        "b M\n"
        f"m {_hex_bytes(a_seed)}\n"
        "r 1 x b\n"
        "n a\n"
    )
    b_object = "OBJ1\nx b 0 1\nb M\nm 60\nn b\n"
    extra_objects: dict[str, str] = {}
    extra_library_objects: dict[str, str] = {}
    if project_dependency:
        extra_objects["A.OBJ"] = a_object
        extra_library_objects["A.OBJ"] = "OBJ1\nx a 0 1\nb M\nm EA\nn a\n"
    else:
        extra_library_objects["A.OBJ"] = a_object
    if project_tail:
        extra_objects["B.OBJ"] = b_object
        extra_library_objects["B.OBJ"] = "OBJ1\nx b 0 1\nb M\nm EA\nn b\n"
    else:
        extra_library_objects["B.OBJ"] = b_object
    expected_loads = [
        "OBJ/A.OBJ" if project_dependency else "LIB/A.OBJ",
        "OBJ/B.OBJ" if project_tail else "LIB/B.OBJ",
    ]
    unexpected_loads = [
        "LIB/A.OBJ" if project_dependency else "OBJ/A.OBJ",
        "LIB/B.OBJ" if project_tail else "OBJ/B.OBJ",
    ]
    case: dict[str, object] = {
        "seed_object": seed_object,
        "has_stub": False,
        "extra_library_objects": extra_library_objects,
        "expected_tail": bytes(root) + bytes(a_expected) + bytes([0x60]),
        "expected_alink_loads": expected_loads,
        "unexpected_alink_loads": unexpected_loads,
    }
    if extra_objects:
        case["extra_objects"] = extra_objects
    return case


