def _runtime_obj_text(name: str) -> str:
    return (UDOS_RUNTIME_MODULES / f"{name}.obj").read_text(encoding="ascii")


def _obj_machine_code(obj_text: str, description: str) -> bytes:
    chunks = [
        bytes.fromhex(line[2:])
        for line in obj_text.splitlines()
        if line.startswith("m ")
    ]
    if not chunks:
        raise RuntimeError(f"OBJ has no machine-code record: {description}")
    return b"".join(chunks)


def _obj_imports(obj_text: str) -> list[str]:
    return [
        line[2:].strip().lower()
        for line in obj_text.splitlines()
        if line.startswith("u ")
    ]


def _obj_exports(obj_text: str, description: str) -> dict[str, int]:
    exports: dict[str, int] = {}
    for line in obj_text.splitlines():
        if not line.startswith("x "):
            continue
        parts = line.split()
        if len(parts) != 4:
            raise RuntimeError(f"unsupported export record in {description}: {line}")
        exports[parts[1].lower()] = int(parts[2])
    return exports


def _obj_relocs(
    obj_text: str, description: str
) -> list[tuple[int, str, int | str, str, int]]:
    relocs: list[tuple[int, str, int | str, str, int]] = []
    for line in obj_text.splitlines():
        if not line.startswith("r "):
            continue
        parts = line.split()
        mode = "word"
        target_index = 2
        selector_mode = parts[2].lower() if len(parts) >= 3 else ""
        if len(parts) >= 4 and selector_mode in {"l", "lo", "h", "hi"}:
            mode = "low" if selector_mode in {"l", "lo"} else "high"
            target_index = 3
        addend = 0
        if (
            len(parts) in {target_index + 1, target_index + 2}
            and parts[target_index].startswith("u")
        ):
            selector = parts[target_index][1:]
            if len(selector) != 1:
                raise RuntimeError(
                    f"unsupported import selector in {description}: {line}"
                )
            if len(parts) == target_index + 2:
                try:
                    addend = int(parts[target_index + 1], 10)
                except ValueError as exc:
                    raise RuntimeError(
                        f"unsupported relocation addend in {description}: {line}"
                    ) from exc
            relocs.append(
                (int(parts[1]), "import", _object_selector_index(selector), mode, addend)
            )
        elif (
            len(parts) in {target_index + 2, target_index + 3}
            and parts[target_index] == "x"
        ):
            if len(parts) == target_index + 3:
                try:
                    addend = int(parts[target_index + 2], 10)
                except ValueError as exc:
                    raise RuntimeError(
                        f"unsupported relocation addend in {description}: {line}"
                    ) from exc
            relocs.append(
                (
                    int(parts[1]),
                    "local",
                    parts[target_index + 1].lower(),
                    mode,
                    addend,
                )
            )
        else:
            raise RuntimeError(f"unsupported relocation record in {description}: {line}")
    return relocs


def _patch_obj_reloc(
    code: bytearray,
    offset: int,
    target_addr: int,
    addend: int,
    mode: str,
    description: str,
) -> None:
    width = 2 if mode == "word" else 1
    if offset < 0 or offset + width > len(code):
        raise RuntimeError(f"relocation offset out of range in {description}: {offset}")
    relocated_addr = target_addr + addend
    if relocated_addr < 0 or relocated_addr > 0xFFFF:
        raise RuntimeError(f"relocation address out of range in {description}: {relocated_addr}")
    if mode == "word":
        code[offset] = relocated_addr & 0xFF
        code[offset + 1] = relocated_addr >> 8
    elif mode == "low":
        code[offset] = relocated_addr & 0xFF
    elif mode == "high":
        code[offset] = relocated_addr >> 8
    else:
        raise RuntimeError(f"unsupported relocation mode in {description}: {mode}")


def _runtime_obj_machine_code(name: str) -> bytes:
    return _obj_machine_code(_runtime_obj_text(name), f"runtime module {name}")


def _runtime_obj_imports(name: str) -> list[str]:
    return _obj_imports(_runtime_obj_text(name))


def _runtime_obj_exports(name: str) -> dict[str, int]:
    return _obj_exports(_runtime_obj_text(name), f"runtime module {name}")


def _runtime_obj_relocs(name: str) -> list[tuple[int, str, int | str, str, int]]:
    return _obj_relocs(_runtime_obj_text(name), f"runtime module {name}")


def _linked_runtime_module_bytes(name: str, module_addrs: dict[str, int]) -> bytes:
    code = bytearray(_runtime_obj_machine_code(name))
    imports = _runtime_obj_imports(name)
    exports = _runtime_obj_exports(name)
    for offset, kind, target, mode, addend in _runtime_obj_relocs(name):
        if kind == "import":
            import_index = int(target)
            if import_index >= len(imports):
                raise RuntimeError(
                    f"relocation import index out of range in {name}: {import_index}"
                )
            target_addr = module_addrs[imports[import_index]]
        else:
            symbol = str(target)
            if symbol not in exports:
                raise RuntimeError(f"local relocation export missing in {name}: {symbol}")
            target_addr = module_addrs[name] + exports[symbol]
        _patch_obj_reloc(
            code, offset, target_addr, addend, mode, f"runtime module {name}"
        )
    return bytes(code)


def _runtime_module_addrs(module_names: list[str], first_addr: int) -> dict[str, int]:
    # Keep hand-built runtime fixtures dependency-complete as OBJ modules gain
    # transitive helpers. Mutating the caller's list also keeps its later byte
    # concatenation and reported library inventory in the same linked order.
    module_names[:] = _runtime_module_closure(module_names)
    addrs: dict[str, int] = {}
    cursor = first_addr
    for name in module_names:
        addrs[name] = cursor
        cursor += len(_runtime_obj_machine_code(name))
    return addrs


def _runtime_module_closure(module_names: list[str]) -> list[str]:
    ordered: list[str] = []
    queued: set[str] = set()
    for name in module_names:
        if name not in queued:
            ordered.append(name)
            queued.add(name)
    index = 0
    while index < len(ordered):
        for import_name in _runtime_obj_imports(ordered[index]):
            if import_name not in queued:
                ordered.append(import_name)
                queued.add(import_name)
        index += 1
    return ordered


def _linked_seed_runtime_tail(seed_object: str) -> bytes:
    description = "seed runtime object"
    code = bytearray(_obj_machine_code(seed_object, description))
    imports = _obj_imports(seed_object)
    exports = _obj_exports(seed_object, description)
    called_modules: list[str] = []
    for line in seed_object.splitlines():
        if not line.startswith("b "):
            continue
        for match in re.finditer(r"u([0-9A-Z])", line):
            import_index = _object_selector_index(match.group(1))
            if import_index >= len(imports):
                raise RuntimeError(
                    f"seed body import index out of range: {import_index}"
                )
            module = imports[import_index]
            if module not in called_modules:
                called_modules.append(module)
    modules = _runtime_module_closure(called_modules)
    module_addrs = _runtime_module_addrs(
        modules, DIRECT_PRG_LOAD_ADDR + len(code)
    )
    for offset, kind, target, mode, addend in _obj_relocs(seed_object, description):
        if kind == "import":
            import_index = int(target)
            if import_index >= len(imports):
                raise RuntimeError(
                    f"seed relocation import index out of range: {import_index}"
                )
            target_addr = module_addrs[imports[import_index]]
        else:
            symbol = str(target)
            if symbol not in exports:
                raise RuntimeError(f"seed local relocation export missing: {symbol}")
            target_addr = DIRECT_PRG_LOAD_ADDR + exports[symbol]
        _patch_obj_reloc(code, offset, target_addr, addend, mode, description)
    return bytes(code) + b"".join(
        _linked_runtime_module_bytes(module, module_addrs) for module in modules
    )


def _runtime_binary_seed_case(
    seed_object: str, runtime_module: str, expected_result: bytes
) -> dict[str, object]:
    if len(expected_result) != 4:
        raise RuntimeError("runtime binary helper result must contain four bytes")
    modules = _runtime_module_closure([runtime_module])
    return {
        "seed_object": seed_object,
        "has_stub": False,
        "runtime_library_objects": modules,
        "expected_tail": _linked_seed_runtime_tail(seed_object),
        "store_check_addr": 0x03D1,
        "store_check_value": expected_result[0],
        "store_check_hi_addr": 0x03D2,
        "store_check_hi_value": expected_result[1],
        "extra_store_checks": [
            {"addr": 0x03D3, "value": expected_result[2]},
            {"addr": 0x03D4, "value": expected_result[3]},
        ],
        "expected_alink_loads": [
            f"LIB/{module.upper()}.OBJ" for module in modules
        ],
        "unexpected_alink_loads": ["LIB/RT_S_TO_F.OBJ"],
    }


def _set_zp_word(zp_addr: int, value: int) -> bytes:
    return bytes(
        [
            0xA9,
            value & 0xFF,
            0x85,
            zp_addr,
            0xA9,
            value >> 8,
            0x85,
            zp_addr + 1,
        ]
    )


def _jsr(addr: int) -> bytes:
    return bytes([0x20, addr & 0xFF, addr >> 8])


def _object_selector_index(value: str) -> int:
    if "0" <= value <= "9":
        return ord(value) - ord("0")
    if "A" <= value <= "Z":
        return ord(value) - ord("A") + 10
    if "a" <= value <= "z":
        return ord(value) - ord("a") + 10
    raise RuntimeError(f"invalid object selector: {value!r}")


def _native_integer_runtime_tail(
    operations: list[tuple[str, int | None]],
    literal_values: list[int],
    var_values: list[int],
    module_names: list[str],
) -> bytes:
    instruction_sizes = {
        "literal": 6,
        "load": 9,
        "store": 11,
        "add": 19,
        "sub": 19,
        "mul": 23,
        "div": 23,
        "eq_if": 23,
        "ne_if": 23,
        "lt_if": 22,
        "gt_if": 24,
        "ge_if": 22,
        "le_if": 24,
        "do": 0,
        "until_eq": 23,
        "until_lt": 22,
        "while_eq": 23,
        "while_ne": 23,
        "while_lt": 22,
        "while_gt": 24,
        "while_ge": 22,
        "while_le": 24,
        "while_end": 3,
        "else": 3,
        "endif": 0,
        "print": 6,
        "println": 11,
        "return": len(_DIRECT_PRG_EXIT_MARKER),
    }
    code_len = 13 if var_values else 0
    depth = 0
    control_stack: list[tuple[int, int | None]] = []
    loop_stack: list[int] = []
    while_stack: list[tuple[int, int]] = []
    control_targets: dict[int, int] = {}
    for op_index, (op, operand) in enumerate(operations):
        if op == "literal":
            if operand is None or operand >= len(literal_values):
                raise RuntimeError(f"literal selector out of range: {operand}")
            depth += 1
        elif op == "load":
            if operand is None or operand >= len(var_values):
                raise RuntimeError(f"variable selector out of range: {operand}")
            depth += 1
        elif op == "store":
            if operand is None or operand >= len(var_values) or depth < 1:
                raise RuntimeError(f"invalid variable store: {operand}")
            depth -= 1
        elif op in {"add", "sub", "mul", "div"}:
            if depth < 2:
                raise RuntimeError(f"stack underflow at binary op {op!r}")
            depth -= 1
        elif op in {"eq_if", "ne_if", "lt_if", "gt_if", "ge_if", "le_if"}:
            if depth < 2:
                raise RuntimeError("stack underflow at integer comparison IF")
            depth -= 2
            control_stack.append((op_index, None))
        elif op == "do":
            loop_stack.append(code_len)
        elif op in {"until_eq", "until_lt"}:
            if depth < 2 or not loop_stack:
                raise RuntimeError(f"invalid native integer loop condition {op!r}")
            depth -= 2
            control_targets[op_index] = loop_stack.pop()
        elif op in {"while_eq", "while_ne", "while_lt", "while_gt", "while_ge", "while_le"}:
            if depth < 2 or not loop_stack:
                raise RuntimeError("invalid native integer WHILE condition")
            depth -= 2
            while_stack.append((op_index, loop_stack[-1]))
        elif op == "while_end":
            if not while_stack or not loop_stack:
                raise RuntimeError("unmatched native integer WHILE end")
            condition_index, loop_head = while_stack.pop()
            if loop_stack.pop() != loop_head:
                raise RuntimeError("mismatched native integer WHILE loop")
            control_targets[condition_index] = code_len + instruction_sizes[op]
            control_targets[op_index] = loop_head
        elif op == "else":
            if not control_stack or control_stack[-1][1] is not None:
                raise RuntimeError("unmatched native integer ELSE")
            if_op_index, _ = control_stack.pop()
            control_targets[if_op_index] = code_len + instruction_sizes[op]
            control_stack.append((if_op_index, op_index))
        elif op == "endif":
            if not control_stack:
                raise RuntimeError("unmatched native integer IF end")
            if_op_index, else_op_index = control_stack.pop()
            control_targets[if_op_index if else_op_index is None else else_op_index] = code_len
        elif op in {"print", "println"}:
            if depth < 1:
                raise RuntimeError(f"stack underflow at print op {op!r}")
            depth -= 1
        elif op == "return":
            if (
                depth != 0
                or control_stack
                or loop_stack
                or while_stack
                or operations[-1][0] != "return"
            ):
                raise RuntimeError("invalid native integer return")
        else:
            raise RuntimeError(f"unsupported native integer operation: {op!r}")
        code_len += instruction_sizes[op]

    data_size = 2 * len(var_values)
    pointer_size = 2 if var_values else 0
    root_len = code_len + data_size + pointer_size
    data_addr = DIRECT_PRG_LOAD_ADDR + code_len
    pointer_addr = data_addr + data_size
    modules = _runtime_module_closure(module_names)
    module_addrs = _runtime_module_addrs(modules, DIRECT_PRG_LOAD_ADDR + root_len)

    code = bytearray()
    if var_values:
        code.extend(
            [
                0xA2,
                0x00,
                0xBD,
                pointer_addr & 0xFF,
                pointer_addr >> 8,
                0x85,
                0x06,
                0xE8,
                0xBD,
                pointer_addr & 0xFF,
                pointer_addr >> 8,
                0x85,
                0x07,
            ]
        )
    for op_index, (op, operand) in enumerate(operations):
        if op == "literal":
            assert operand is not None
            value = literal_values[operand] & 0xFFFF
            code.extend([0xA9, value & 0xFF, 0x48, 0xA9, value >> 8, 0x48])
        elif op == "load":
            assert operand is not None
            code.extend([0xA0, operand * 2, 0xB1, 0x06, 0x48, 0xC8, 0xB1, 0x06, 0x48])
        elif op == "store":
            assert operand is not None
            code.extend([0x68, 0xAA, 0x68, 0xA0, operand * 2, 0x91, 0x06, 0xC8, 0x8A, 0x91, 0x06])
        elif op in {"add", "sub"}:
            carry = 0x18 if op == "add" else 0x38
            arithmetic = 0x65 if op == "add" else 0xE5
            code.extend(
                [
                    0x68,
                    0x85,
                    0x05,
                    0x68,
                    0x85,
                    0x04,
                    0x68,
                    0x85,
                    0x03,
                    0x68,
                    carry,
                    arithmetic,
                    0x04,
                    0x48,
                    0xA5,
                    0x03,
                    arithmetic,
                    0x05,
                    0x48,
                ]
            )
        elif op in {"mul", "div"}:
            helper = "rt_i_mul" if op == "mul" else "rt_i_div"
            code.extend(
                [
                    0xA9,
                    0x04,
                    0x85,
                    0x02,
                    0xA9,
                    0x00,
                    0x85,
                    0x03,
                    0x68,
                    0x85,
                    0x05,
                    0x68,
                    0x85,
                    0x04,
                    0x68,
                    0xAA,
                    0x68,
                ]
            )
            code.extend(_jsr(module_addrs[helper]))
            code.extend([0x48, 0x8A, 0x48])
        elif op in {"eq_if", "ne_if", "until_eq", "while_eq", "while_ne"}:
            target_addr = DIRECT_PRG_LOAD_ADDR + control_targets[op_index]
            is_equal = op in {"eq_if", "until_eq", "while_eq"}
            low_branch_offset = 0x06 if is_equal else 0x09
            high_branch_opcode = 0xF0 if is_equal else 0xD0
            code.extend(
                [
                    0x68,
                    0x85,
                    0x05,
                    0x68,
                    0x85,
                    0x04,
                    0x68,
                    0x85,
                    0x03,
                    0x68,
                    0xC5,
                    0x04,
                    0xD0,
                    low_branch_offset,
                    0xA5,
                    0x03,
                    0xC5,
                    0x05,
                    high_branch_opcode,
                    0x03,
                    0x4C,
                    target_addr & 0xFF,
                    target_addr >> 8,
                ]
            )
        elif op in {"lt_if", "until_lt", "while_lt"}:
            target_addr = DIRECT_PRG_LOAD_ADDR + control_targets[op_index]
            code.extend(
                [
                    0x68,
                    0x85,
                    0x05,
                    0x68,
                    0x85,
                    0x04,
                    0x68,
                    0xAA,
                    0x68,
                    0xE4,
                    0x05,
                    0x90,
                    0x09,
                    0xD0,
                    0x04,
                    0xC5,
                    0x04,
                    0x90,
                    0x03,
                    0x4C,
                    target_addr & 0xFF,
                    target_addr >> 8,
                ]
            )
        elif op in {"gt_if", "while_gt"}:
            target_addr = DIRECT_PRG_LOAD_ADDR + control_targets[op_index]
            code.extend(
                [
                    0x68,
                    0x85,
                    0x05,
                    0x68,
                    0x85,
                    0x04,
                    0x68,
                    0xAA,
                    0x68,
                    0xE4,
                    0x05,
                    0x90,
                    0x08,
                    0xD0,
                    0x09,
                    0xC5,
                    0x04,
                    0x90,
                    0x02,
                    0xD0,
                    0x03,
                    0x4C,
                    target_addr & 0xFF,
                    target_addr >> 8,
                ]
            )
        elif op in {"ge_if", "while_ge"}:
            target_addr = DIRECT_PRG_LOAD_ADDR + control_targets[op_index]
            code.extend(
                [
                    0x68,
                    0x85,
                    0x05,
                    0x68,
                    0x85,
                    0x04,
                    0x68,
                    0xAA,
                    0x68,
                    0xE4,
                    0x05,
                    0x90,
                    0x06,
                    0xD0,
                    0x07,
                    0xC5,
                    0x04,
                    0xB0,
                    0x03,
                    0x4C,
                    target_addr & 0xFF,
                    target_addr >> 8,
                ]
            )
        elif op in {"le_if", "while_le"}:
            target_addr = DIRECT_PRG_LOAD_ADDR + control_targets[op_index]
            code.extend(
                [
                    0x68,
                    0x85,
                    0x05,
                    0x68,
                    0x85,
                    0x04,
                    0x68,
                    0xAA,
                    0x68,
                    0xE4,
                    0x05,
                    0x90,
                    0x0B,
                    0xD0,
                    0x06,
                    0xC5,
                    0x04,
                    0x90,
                    0x05,
                    0xF0,
                    0x03,
                    0x4C,
                    target_addr & 0xFF,
                    target_addr >> 8,
                ]
            )
        elif op == "else":
            target_addr = DIRECT_PRG_LOAD_ADDR + control_targets[op_index]
            code.extend([0x4C, target_addr & 0xFF, target_addr >> 8])
        elif op == "endif":
            pass
        elif op == "do":
            pass
        elif op == "while_end":
            target_addr = DIRECT_PRG_LOAD_ADDR + control_targets[op_index]
            code.extend([0x4C, target_addr & 0xFF, target_addr >> 8])
        elif op in {"print", "println"}:
            code.extend([0x68, 0xAA, 0x68])
            code.extend(_jsr(module_addrs["rt_print_i"]))
            if op == "println":
                code.extend(bytes([0xA9, 0x0D, 0x20, 0xD2, 0xFF]))
        elif op == "return":
            code.extend(_DIRECT_PRG_EXIT_MARKER)

    root = bytes(code) + b"".join(
        (value & 0xFFFF).to_bytes(2, "little") for value in var_values
    )
    if var_values:
        root += data_addr.to_bytes(2, "little")
    if len(root) != root_len:
        raise RuntimeError(f"unexpected native integer root size: {len(root)} != {root_len}")
    return root + b"".join(_linked_runtime_module_bytes(module, module_addrs) for module in modules)


def _native_local_integer_runtime_tail(
    procedures: list[list[tuple[str, int | None]]],
    literal_values: list[int],
    var_values: list[int],
) -> bytes:
    """Build the expected linked image for ACTC's multi-procedure integer pass."""
    instruction_sizes = {
        "literal": 6,
        "load": 9,
        "store": 11,
        "eq_if": 23,
        "do": 0,
        "until_eq": 23,
        "while_lt": 22,
        "while_end": 3,
        "else": 3,
        "endif": 0,
        "local_call": 3,
    }
    main_index = len(procedures) - 1
    proc_offsets: dict[int, int] = {}
    proc_targets: dict[int, dict[int, int]] = {}
    code_len = 13 if var_values else 0

    for proc_index in range(main_index, -1, -1):
        proc_offsets[proc_index] = code_len
        depth = 0
        controls: list[tuple[str, int, int | None]] = []
        targets: dict[int, int] = {}
        operations = procedures[proc_index]
        for op_index, (op, operand) in enumerate(operations):
            if op == "literal":
                if operand is None or operand >= len(literal_values):
                    raise RuntimeError(f"literal selector out of range: {operand}")
                depth += 1
            elif op == "load":
                if operand is None or operand >= len(var_values):
                    raise RuntimeError(f"variable selector out of range: {operand}")
                depth += 1
            elif op == "store":
                if operand is None or operand >= len(var_values) or depth < 1:
                    raise RuntimeError(f"invalid variable store: {operand}")
                depth -= 1
            elif op == "eq_if":
                if depth < 2:
                    raise RuntimeError("stack underflow at local integer IF")
                depth -= 2
                controls.append(("if", op_index, None))
            elif op == "do":
                if depth != 0:
                    raise RuntimeError("non-empty stack at local integer DO")
                controls.append(("do", op_index, code_len))
            elif op == "until_eq":
                if depth < 2 or not controls or controls[-1][0] != "do":
                    raise RuntimeError("invalid local integer UNTIL")
                depth -= 2
                _, _, loop_target = controls.pop()
                assert loop_target is not None
                targets[op_index] = loop_target
            elif op == "while_lt":
                if depth < 2 or not controls or controls[-1][0] != "do":
                    raise RuntimeError("invalid local integer WHILE")
                depth -= 2
                _, _, loop_target = controls.pop()
                controls.append(("while", op_index, loop_target))
            elif op == "while_end":
                if not controls or controls[-1][0] != "while":
                    raise RuntimeError("unmatched local integer WHILE end")
                _, while_index, loop_target = controls.pop()
                assert loop_target is not None
                targets[while_index] = code_len + instruction_sizes[op]
                targets[op_index] = loop_target
            elif op == "else":
                if not controls or controls[-1][0] != "if" or controls[-1][2] is not None:
                    raise RuntimeError("unmatched local integer ELSE")
                _, if_index, _ = controls.pop()
                targets[if_index] = code_len + instruction_sizes[op]
                controls.append(("if", if_index, op_index))
            elif op == "endif":
                if not controls or controls[-1][0] != "if":
                    raise RuntimeError("unmatched local integer IF end")
                _, if_index, else_index = controls.pop()
                targets[if_index if else_index is None else else_index] = code_len
            elif op == "local_call":
                if depth != 0 or operand is None or operand >= main_index:
                    raise RuntimeError(f"invalid local procedure call: {operand}")
            elif op == "return":
                if depth != 0 or controls or op_index != len(operations) - 1:
                    raise RuntimeError("invalid local integer return")
                code_len += len(_DIRECT_PRG_EXIT_MARKER) if proc_index == main_index else 1
                continue
            else:
                raise RuntimeError(f"unsupported local integer operation: {op!r}")
            code_len += instruction_sizes[op]
        proc_targets[proc_index] = targets

    data_size = 2 * len(var_values)
    data_addr = DIRECT_PRG_LOAD_ADDR + code_len
    pointer_addr = data_addr + data_size
    code = bytearray()
    if var_values:
        code.extend(
            [
                0xA2,
                0x00,
                0xBD,
                pointer_addr & 0xFF,
                pointer_addr >> 8,
                0x85,
                0x06,
                0xE8,
                0xBD,
                pointer_addr & 0xFF,
                pointer_addr >> 8,
                0x85,
                0x07,
            ]
        )

    for proc_index in range(main_index, -1, -1):
        for op_index, (op, operand) in enumerate(procedures[proc_index]):
            if op == "literal":
                assert operand is not None
                value = literal_values[operand] & 0xFFFF
                code.extend([0xA9, value & 0xFF, 0x48, 0xA9, value >> 8, 0x48])
            elif op == "load":
                assert operand is not None
                code.extend([0xA0, operand * 2, 0xB1, 0x06, 0x48, 0xC8, 0xB1, 0x06, 0x48])
            elif op == "store":
                assert operand is not None
                code.extend([0x68, 0xAA, 0x68, 0xA0, operand * 2, 0x91, 0x06, 0xC8, 0x8A, 0x91, 0x06])
            elif op in {"eq_if", "until_eq"}:
                target = DIRECT_PRG_LOAD_ADDR + proc_targets[proc_index][op_index]
                code.extend(
                    [
                        0x68,
                        0x85,
                        0x05,
                        0x68,
                        0x85,
                        0x04,
                        0x68,
                        0x85,
                        0x03,
                        0x68,
                        0xC5,
                        0x04,
                        0xD0,
                        0x06,
                        0xA5,
                        0x03,
                        0xC5,
                        0x05,
                        0xF0,
                        0x03,
                        0x4C,
                        target & 0xFF,
                        target >> 8,
                    ]
                )
            elif op == "while_lt":
                target = DIRECT_PRG_LOAD_ADDR + proc_targets[proc_index][op_index]
                code.extend(
                    [
                        0x68,
                        0x85,
                        0x05,
                        0x68,
                        0x85,
                        0x04,
                        0x68,
                        0xAA,
                        0x68,
                        0xE4,
                        0x05,
                        0x90,
                        0x09,
                        0xD0,
                        0x04,
                        0xC5,
                        0x04,
                        0x90,
                        0x03,
                        0x4C,
                        target & 0xFF,
                        target >> 8,
                    ]
                )
            elif op == "else":
                target = DIRECT_PRG_LOAD_ADDR + proc_targets[proc_index][op_index]
                code.extend([0x4C, target & 0xFF, target >> 8])
            elif op == "local_call":
                assert operand is not None
                code.extend(_jsr(DIRECT_PRG_LOAD_ADDR + proc_offsets[operand]))
            elif op in {"do", "endif"}:
                pass
            elif op == "while_end":
                target = DIRECT_PRG_LOAD_ADDR + proc_targets[proc_index][op_index]
                code.extend([0x4C, target & 0xFF, target >> 8])
            elif op == "return":
                code.extend(_DIRECT_PRG_EXIT_MARKER if proc_index == main_index else b"\x60")

    root = bytes(code) + b"".join(
        (value & 0xFFFF).to_bytes(2, "little") for value in var_values
    )
    if var_values:
        root += data_addr.to_bytes(2, "little")
    expected_len = code_len + data_size + (2 if var_values else 0)
    if len(root) != expected_len:
        raise RuntimeError(f"unexpected native local integer root size: {len(root)} != {expected_len}")
    return root


def _native_printmath_tail() -> bytes:
    root_code_len = 262
    root_data = b"\x00\x00HELLO\x00"
    root_len = root_code_len + len(root_data) + 2
    work_len = 46
    work_addr = DIRECT_PRG_LOAD_ADDR + root_len
    print_addr = work_addr + work_len
    root_data_addr = DIRECT_PRG_LOAD_ADDR + root_code_len
    root_pointer_addr = root_data_addr + len(root_data)

    root = bytearray(
        [
            0xA2,
            0x00,
            0xBD,
            root_pointer_addr & 0xFF,
            root_pointer_addr >> 8,
            0x85,
            0x06,
            0xE8,
            0xBD,
            root_pointer_addr & 0xFF,
            root_pointer_addr >> 8,
            0x85,
            0x07,
            0xA5,
            0x06,
            0x18,
            0x69,
            0x02,
            0x85,
            0x02,
            0xA5,
            0x07,
            0x69,
            0x00,
            0x85,
            0x03,
            0xA2,
            0x02,
            0x20,
            0x03,
            0xCF,
            0x20,
            0x06,
            0xCF,
        ]
    )
    root.extend(_jsr(work_addr))

    def push_literal(value: int) -> None:
        root.extend([0xA9, value & 0xFF, 0x48, 0xA9, value >> 8, 0x48])

    def load_x() -> None:
        root.extend([0xA0, 0x00, 0xB1, 0x06, 0x48, 0xC8, 0xB1, 0x06, 0x48])

    def store_x() -> None:
        root.extend([0x68, 0xAA, 0x68, 0xA0, 0x00, 0x91, 0x06, 0xC8, 0x8A, 0x91, 0x06])

    def binary(subtract: bool) -> None:
        carry = 0x38 if subtract else 0x18
        arithmetic = 0xE5 if subtract else 0x65
        root.extend(
            [
                0x68,
                0x85,
                0x05,
                0x68,
                0x85,
                0x04,
                0x68,
                0x85,
                0x03,
                0x68,
                carry,
                arithmetic,
                0x04,
                0x48,
                0xA5,
                0x03,
                arithmetic,
                0x05,
                0x48,
            ]
        )

    def print_x(newline: bool) -> None:
        root.extend([0x68, 0xAA, 0x68])
        root.extend(_jsr(print_addr))
        if newline:
            root.extend([0xA9, 0x0D, 0x20, 0xD2, 0xFF])

    push_literal(50)
    store_x()
    load_x()
    push_literal(7)
    binary(False)
    push_literal(3)
    binary(True)
    store_x()
    load_x()
    print_x(False)
    push_literal(60)
    store_x()
    load_x()
    push_literal(3)
    binary(True)
    push_literal(2)
    binary(False)
    store_x()
    load_x()
    print_x(True)
    root.extend(_DIRECT_PRG_EXIT_MARKER)
    if len(root) != root_code_len:
        raise RuntimeError(f"unexpected native printmath code size: {len(root)}")
    root.extend(root_data)
    root.extend(root_data_addr.to_bytes(2, "little"))

    work_code_len = 39
    work_data = b"WIDG\x00"
    work_data_addr = work_addr + work_code_len
    work_pointer_addr = work_data_addr + len(work_data)
    work = bytearray(
        [
            0xA2,
            0x00,
            0xBD,
            work_pointer_addr & 0xFF,
            work_pointer_addr >> 8,
            0x85,
            0x06,
            0xE8,
            0xBD,
            work_pointer_addr & 0xFF,
            work_pointer_addr >> 8,
            0x85,
            0x07,
            0xA5,
            0x06,
            0x18,
            0x69,
            0x00,
            0x85,
            0x02,
            0xA5,
            0x07,
            0x69,
            0x00,
            0x85,
            0x03,
            0xA2,
            0x02,
            0x20,
            0x03,
            0xCF,
            0xA9,
            0x2A,
            0xA2,
            0x00,
        ]
    )
    work.extend(_jsr(print_addr))
    work.append(0x60)
    if len(work) != work_code_len:
        raise RuntimeError(f"unexpected native printmath library code size: {len(work)}")
    work.extend(work_data)
    work.extend(work_data_addr.to_bytes(2, "little"))
    if len(work) != work_len:
        raise RuntimeError(f"unexpected native printmath library size: {len(work)}")

    module_addrs = {"rt_print_i": print_addr}
    return bytes(root + work) + _linked_runtime_module_bytes("rt_print_i", module_addrs)


def _actc_selective_hardware_runtime_tail() -> bytes:
    modules = ["rt_sprite_data", "rt_sprite_pos", "rt_gfx_bgcolor", "rt_sid_freq"]
    root_len = 49
    module_addrs = _runtime_module_addrs(modules, DIRECT_PRG_LOAD_ADDR + root_len)
    code = (
        bytes([0xA9, 0x02, 0xA2, 0x00, 0xA0, 0x20])
        + _jsr(module_addrs["rt_sprite_data"])
        + bytes([0xA9, 0x02, 0xA2, 0x34, 0xA0, 0x56, 0x38])
        + _jsr(module_addrs["rt_sprite_pos"])
        + bytes([0xA9, 0x06])
        + _jsr(module_addrs["rt_gfx_bgcolor"])
        + bytes([0xA9, 0x01, 0xA2, 0x34, 0xA0, 0x12])
        + _jsr(module_addrs["rt_sid_freq"])
        + _DIRECT_PRG_EXIT_MARKER
    )
    if len(code) != root_len:
        raise RuntimeError(f"unexpected selective hardware root size: {len(code)}")
    return code + b"".join(
        _linked_runtime_module_bytes(module, module_addrs) for module in modules
    )


def _actc_reordered_hardware_runtime_tail() -> bytes:
    modules = ["rt_gfx_bgcolor", "rt_sid_freq", "rt_sprite_data"]
    root_len = 39
    module_addrs = _runtime_module_addrs(modules, DIRECT_PRG_LOAD_ADDR + root_len)
    code = (
        bytes([0xA9, 0x03])
        + _jsr(module_addrs["rt_gfx_bgcolor"])
        + bytes([0xA9, 0x01, 0xA2, 0x34, 0xA0, 0x12])
        + _jsr(module_addrs["rt_sid_freq"])
        + bytes([0xA9, 0x02, 0xA2, 0x00, 0xA0, 0x20])
        + _jsr(module_addrs["rt_sprite_data"])
        + _DIRECT_PRG_EXIT_MARKER
    )
    if len(code) != root_len:
        raise RuntimeError(f"unexpected reordered hardware root size: {len(code)}")
    return code + b"".join(
        _linked_runtime_module_bytes(module, module_addrs) for module in modules
    )


def _actc_repeated_bgcolor_runtime_tail() -> bytes:
    modules = ["rt_gfx_bgcolor"]
    root_len = 26
    module_addrs = _runtime_module_addrs(modules, DIRECT_PRG_LOAD_ADDR + root_len)
    code = (
        bytes([0xA9, 0x02])
        + _jsr(module_addrs["rt_gfx_bgcolor"])
        + bytes([0xA9, 0x06])
        + _jsr(module_addrs["rt_gfx_bgcolor"])
        + _DIRECT_PRG_EXIT_MARKER
    )
    if len(code) != root_len:
        raise RuntimeError(f"unexpected repeated BgColor root size: {len(code)}")
    return code + b"".join(
        _linked_runtime_module_bytes(module, module_addrs) for module in modules
    )


def _actc_named_hardware_constants_runtime_tail() -> bytes:
    call_specs: list[tuple[str, str, int, int | None]] = [
        ("ay", "rt_sid_wave", 1, 0xF0),
        ("a", "rt_sid_mode", 0x70, None),
        ("ay", "rt_sprite_prio", 2, 1),
        ("ay", "rt_sprite_prio", 3, 0),
    ]
    root_len = len(_DIRECT_PRG_EXIT_MARKER) + sum(
        7 if kind == "ay" else 5 for kind, _, _, _ in call_specs
    )
    modules = _runtime_module_closure([name for _, name, _, _ in call_specs])
    module_addrs = _runtime_module_addrs(modules, DIRECT_PRG_LOAD_ADDR + root_len)
    code = bytearray()
    for kind, name, arg0, arg1 in call_specs:
        if kind == "ay":
            if arg1 is None:
                raise RuntimeError(f"missing AY helper second argument for {name}")
            code.extend([0xA9, arg0 & 0xFF, 0xA0, arg1 & 0xFF])
