def _real_to_int_tail(value: int) -> bytes:
    modules = ["rt_i_to_f", "rt_f_to_i"]
    root_len = 66
    code_len = 58
    real_var = DIRECT_PRG_LOAD_ADDR + code_len
    int_var = real_var + 4
    pointer_table = int_var + 2
    module_addrs = _runtime_module_addrs(modules, DIRECT_PRG_LOAD_ADDR + root_len)

    def load_zp2_from_table(index: int) -> bytes:
        return bytes(
            [
                0xA2,
                index,
                0xBD,
                pointer_table & 0xFF,
                pointer_table >> 8,
                0x85,
                0x02,
                0xE8,
                0xBD,
                pointer_table & 0xFF,
                pointer_table >> 8,
                0x85,
                0x03,
            ]
        )

    code = (
        load_zp2_from_table(0)
        + bytes([0xA9, value & 0xFF, 0xA2, (value >> 8) & 0xFF])
        + _jsr(module_addrs["rt_i_to_f"])
        + load_zp2_from_table(0)
        + _jsr(module_addrs["rt_f_to_i"])
        + bytes(
            [
                0x8D,
                int_var & 0xFF,
                int_var >> 8,
                0x8E,
                (int_var + 1) & 0xFF,
                (int_var + 1) >> 8,
            ]
        )
        + _DIRECT_PRG_EXIT_MARKER
    )
    if len(code) != code_len:
        raise RuntimeError(f"unexpected REAL INT root size: {len(code)}")
    return code + bytes(6) + bytes([real_var & 0xFF, real_var >> 8]) + b"".join(
        _linked_runtime_module_bytes(module, module_addrs) for module in modules
    )


def _real_printre_binary_tail(left: int, right: int, op_module: str) -> bytes:
    modules = _runtime_module_closure(["rt_i_to_f", op_module, "rt_print_f"])
    module_addrs = _runtime_module_addrs(modules, 0x1084)
    real_a = 0x1072
    real_b = 0x1076
    real_x = 0x107A
    pointer_table = 0x107E

    def load_zp_from_table(index: int, zp: int) -> bytes:
        return bytes(
            [
                0xA2,
                index,
                0xBD,
                pointer_table & 0xFF,
                pointer_table >> 8,
                0x85,
                zp,
                0xE8,
                0xBD,
                pointer_table & 0xFF,
                pointer_table >> 8,
                0x85,
                zp + 1,
            ]
        )

    code = (
        load_zp_from_table(0, 0x02)
        + bytes([0xA9, left & 0xFF, 0xA2, (left >> 8) & 0xFF])
        + _jsr(module_addrs["rt_i_to_f"])
        + load_zp_from_table(2, 0x02)
        + bytes([0xA9, right & 0xFF, 0xA2, (right >> 8) & 0xFF])
        + _jsr(module_addrs["rt_i_to_f"])
        + load_zp_from_table(0, 0x02)
        + load_zp_from_table(2, 0x04)
        + load_zp_from_table(4, 0x06)
        + _jsr(module_addrs[op_module])
        + load_zp_from_table(4, 0x02)
        + _jsr(module_addrs["rt_print_f"])
        + _DIRECT_PRG_EXIT_MARKER
    )
    if len(code) != 114:
        raise RuntimeError(f"unexpected REAL PrintRE binary root size: {len(code)}")
    pointer_data = bytes(
        [
            real_a & 0xFF,
            real_a >> 8,
            real_b & 0xFF,
            real_b >> 8,
            real_x & 0xFF,
            real_x >> 8,
        ]
    )
    return code + bytes(12) + pointer_data + b"".join(
        _linked_runtime_module_bytes(module, module_addrs) for module in modules
    )


