def _real_printre_unary_tail(value: int, convert_module: str, unary_module: str) -> bytes:
    modules = _runtime_module_closure([convert_module, unary_module, "rt_print_f"])
    module_addrs = _runtime_module_addrs(modules, 0x105D)
    real_a = 0x1051
    real_x = 0x1055
    pointer_table = 0x1059

    def load_zp_from_table(index: int, zp: int) -> bytes:
        return bytes(
            [
                0xA2,
                index,
                0xBD,
                pointer_table & 0xFF,
                pointer_table >> 8,
                0x85,
                zp,
                0xE8,
                0xBD,
                pointer_table & 0xFF,
                pointer_table >> 8,
                0x85,
                zp + 1,
            ]
        )

    code = (
        load_zp_from_table(0, 0x02)
        + bytes([0xA9, value & 0xFF, 0xA2, (value >> 8) & 0xFF])
        + _jsr(module_addrs[convert_module])
        + load_zp_from_table(0, 0x02)
        + load_zp_from_table(2, 0x06)
        + _jsr(module_addrs[unary_module])
        + load_zp_from_table(2, 0x02)
        + _jsr(module_addrs["rt_print_f"])
        + _DIRECT_PRG_EXIT_MARKER
    )
    if len(code) != 81:
        raise RuntimeError(f"unexpected REAL PrintRE unary root size: {len(code)}")
    pointer_data = bytes(
        [real_a & 0xFF, real_a >> 8, real_x & 0xFF, real_x >> 8]
    )
    return code + bytes(8) + pointer_data + b"".join(
        _linked_runtime_module_bytes(module, module_addrs) for module in modules
    )


def _real_printre_fabs_tail(value: int) -> bytes:
    return _real_printre_unary_tail(value, "rt_s_to_f", "rt_f_abs")


def _real_printre_fsqrt_tail(value: int) -> bytes:
    return _real_printre_unary_tail(value, "rt_i_to_f", "rt_f_sqrt")


