def _real_input_printre_tail(stored_result: bool) -> bytes:
    modules = _runtime_module_closure(["rt_joy", "rt_i_to_f", "rt_print_f"])
    root_len = 76 if stored_result else 66
    code_len = 68 if stored_result else 60
    data_base = DIRECT_PRG_LOAD_ADDR + code_len
    real_value = data_base + 2 if stored_result else data_base
    pointer_table = real_value + 4
    module_addrs = _runtime_module_addrs(modules, DIRECT_PRG_LOAD_ADDR + root_len)

    def load_zp2_from_table() -> bytes:
        return bytes(
            [
                0xA2,
                0x00,
                0xBD,
                pointer_table & 0xFF,
                pointer_table >> 8,
                0x85,
                0x02,
                0xE8,
                0xBD,
                pointer_table & 0xFF,
                pointer_table >> 8,
                0x85,
                0x03,
            ]
        )

    code = bytearray([0xA9, 0x02, 0xAA, 0xA0, 0x00])
    code.extend(_jsr(module_addrs["rt_joy"]))
    if stored_result:
        code.extend(
            [
                0x8D,
                data_base & 0xFF,
                data_base >> 8,
                0xA9,
                0x00,
                0x8D,
                (data_base + 1) & 0xFF,
                (data_base + 1) >> 8,
            ]
        )
    code.extend(load_zp2_from_table())
    code.extend([0xA9, 0x07, 0xA2, 0x00])
    code.extend(_jsr(module_addrs["rt_i_to_f"]))
    code.extend(load_zp2_from_table())
    code.extend(_jsr(module_addrs["rt_print_f"]))
    code.extend(_DIRECT_PRG_EXIT_MARKER)
    if len(code) != code_len:
        raise RuntimeError(f"unexpected REAL input/print root size: {len(code)}")
    return (
        bytes(code)
        + bytes(6 if stored_result else 4)
        + bytes([real_value & 0xFF, real_value >> 8])
        + b"".join(_linked_runtime_module_bytes(module, module_addrs) for module in modules)
    )


