        f"{_RUNTIME_CONDITION_EXIT_OBJECT_BYTES}\n",
        "r 3 u0\nr 12 u1\n",
        f"u {helper_name}\n",
        "u rt_gfx_bgcolor\n",
        f"i {helper_arg & 0xFF}\n",
        f"i {compare_value & 0xFF}\n",
        f"i {side_arg & 0xFF}\n",
