def _object_code_named_dual_import_dependencies_case(
    *,
    project_a: bool,
    project_b: bool,
    project_c: bool,
) -> dict[str, object]:
    a_object = (
        "OBJ1\n"
        "x a 0 7\n"
        "b M\n"
        "b M\n"
        "m 20 00 00 20 00 00 60\n"
        "r 1 x b\n"
        "r 4 x c\n"
        "n a\n"
    )
    b_object = "OBJ1\nx b 0 1\nb M\nm 60\nn b\n"
    c_object = "OBJ1\nx c 0 1\nb M\nm 60\nn c\n"
    extra_objects: dict[str, str] = {}
    extra_library_objects: dict[str, str] = {}
    for name, text, project_local in (
        ("A.OBJ", a_object, project_a),
        ("B.OBJ", b_object, project_b),
        ("C.OBJ", c_object, project_c),
    ):
        if project_local:
            extra_objects[name] = text
            export_name = name.removesuffix(".OBJ").lower()
            extra_library_objects[name] = f"OBJ1\nx {export_name} 0 1\nb M\nm EA\nn {export_name}\n"
        else:
            extra_library_objects[name] = text
    expected_loads = [
        "OBJ/A.OBJ" if project_a else "LIB/A.OBJ",
        "OBJ/B.OBJ" if project_b else "LIB/B.OBJ",
        "OBJ/C.OBJ" if project_c else "LIB/C.OBJ",
    ]
    unexpected_loads = [
        "LIB/A.OBJ" if project_a else "OBJ/A.OBJ",
        "LIB/B.OBJ" if project_b else "OBJ/B.OBJ",
        "LIB/C.OBJ" if project_c else "OBJ/C.OBJ",
    ]
    case: dict[str, object] = {
        "seed_object": (
            "OBJ1\n"
            "x main 0 19\n"
            "b u0M\n"
            "u a\n"
            "m 20 00 00 A9 A5 8D D0 03 A9 00 85 02 85 03 A2 02 4C 0F CF\n"
            "r 1 u0\n"
            "n main\n"
        ),
        "has_stub": False,
        "extra_library_objects": extra_library_objects,
        "expected_tail": bytes.fromhex(
            "201310A9A58DD003A90085028503A2024C0FCF201A10201B10606060"
        ),
        "expected_alink_loads": expected_loads,
        "unexpected_alink_loads": unexpected_loads,
    }
    if extra_objects:
        case["extra_objects"] = extra_objects
    return case


def _object_code_named_mixed_closure_case(
    *,
    project_a: bool,
    project_b: bool,
    dual_transitive: bool = False,
) -> dict[str, object]:
    project_c = not project_a
    project_d = not project_b
    a_object = "OBJ1\nx a 0 4\nb M\nm 20 00 00 60\nr 1 x c\nn a\n"
    b_object = (
        "OBJ1\nx b 0 4\nb M\nm 20 00 00 60\nr 1 x d\nn b\n"
        if dual_transitive
        else "OBJ1\nx b 0 1\nb M\nm 60\nn b\n"
    )
    c_object = "OBJ1\nx c 0 1\nb M\nm 60\nn c\n"
    d_object = "OBJ1\nx d 0 1\nb M\nm 60\nn d\n"
    extra_objects: dict[str, str] = {}
    extra_library_objects: dict[str, str] = {}

    def add_object(name: str, text: str, project_local: bool) -> None:
        if project_local:
            extra_objects[name] = text
            export_name = name.removesuffix(".OBJ").lower()
            extra_library_objects[name] = f"OBJ1\nx {export_name} 0 1\nb M\nm EA\nn {export_name}\n"
        else:
            extra_library_objects[name] = text

    add_object("A.OBJ", a_object, project_a)
    add_object("B.OBJ", b_object, project_b)
    add_object("C.OBJ", c_object, project_c)
    if dual_transitive:
        add_object("D.OBJ", d_object, project_d)

    expected_loads = [
        "OBJ/A.OBJ" if project_a else "LIB/A.OBJ",
        "OBJ/B.OBJ" if project_b else "LIB/B.OBJ",
        "OBJ/C.OBJ" if project_c else "LIB/C.OBJ",
    ]
    if dual_transitive:
        expected_loads.append("OBJ/D.OBJ" if project_d else "LIB/D.OBJ")
    unexpected_loads = [
        "LIB/A.OBJ" if project_a else "OBJ/A.OBJ",
        "LIB/B.OBJ" if project_b else "OBJ/B.OBJ",
        "LIB/C.OBJ" if project_c else "OBJ/C.OBJ",
    ]
    if dual_transitive:
        unexpected_loads.append("LIB/D.OBJ" if project_d else "OBJ/D.OBJ")
    expected_tail = (
        "201610201A10A9A58DD003A90085028503A2024C0FCF201E1060201F10606060"
        if dual_transitive
        else "201610201A10A9A58DD003A90085028503A2024C0FCF201B10606060"
    )
    return {
        "seed_object": (
            "OBJ1\n"
            "x main 0 22\n"
            "b u0u1M\n"
            "u a\n"
            "u b\n"
            "m 20 00 00 20 00 00 A9 A5 8D D0 03 A9 00 85 02 85 03 A2 02 4C 0F CF\n"
            "r 1 u0\n"
            "r 4 u1\n"
            "n main\n"
        ),
        "has_stub": False,
        "extra_objects": extra_objects,
        "extra_library_objects": extra_library_objects,
        "expected_tail": bytes.fromhex(expected_tail),
        "expected_alink_loads": expected_loads,
        "unexpected_alink_loads": unexpected_loads,
    }


