def _object_code_external_chain_case(module_count: int) -> dict[str, object]:
    if not 1 <= module_count <= 99:
        raise ValueError("external chain module count must be between 1 and 99")

    module_names = [f"d{index:02d}" for index in range(module_count)]
    root_code = bytearray.fromhex(
        "20 00 00 A9 A5 8D D0 03 A9 00 85 02 85 03 A2 02 4C 0F CF"
    )
    root_code[1:3] = (0x1000 + len(root_code)).to_bytes(2, "little")

    extra_library_objects: dict[str, str] = {}
    expected_tail = bytearray(root_code)
    for index, name in enumerate(module_names):
        if index + 1 == module_count:
            object_text = f"OBJ1\nx {name} 0 1\nb M\nm 60\nn {name}\n"
            linked_code = bytes([0x60])
        else:
            next_name = module_names[index + 1]
            next_address = 0x1000 + len(root_code) + (index + 1) * 4
            object_text = (
                f"OBJ1\nx {name} 0 4\nb u0M\nu {next_name}\n"
                f"m 20 00 00 60\nr 1 u0\nn {name}\n"
            )
            linked_code = bytes(
                [0x20, next_address & 0xFF, next_address >> 8, 0x60]
            )
        extra_library_objects[f"{name.upper()}.OBJ"] = object_text
        expected_tail.extend(linked_code)

    seed_object = (
        "OBJ1\n"
        f"x main 0 {len(root_code)}\n"
        "b u0M\n"
        f"u {module_names[0]}\n"
        f"m {' '.join(f'{byte:02X}' for byte in root_code)}\n"
        "r 1 u0\n"
        "n main\n"
    )
    return {
        "seed_object": seed_object,
        "has_stub": False,
        "extra_library_objects": extra_library_objects,
        "expected_tail": bytes(expected_tail),
        "expected_alink_loads": [
            f"LIB/{name.upper()}.OBJ" for name in module_names
        ],
    }


def _object_code_external_chain_overflow_case(
    module_count: int, external_limit: int
) -> dict[str, object]:
    if module_count <= external_limit:
        raise ValueError("overflow chain must exceed the external-symbol limit")

    case = _object_code_external_chain_case(module_count)
    all_loads = list(case["expected_alink_loads"])
    case.pop("expected_tail")
    case["expected_alink_loads"] = all_loads[:external_limit]
    case["unexpected_alink_loads"] = all_loads[external_limit:]
    case["expect_alink_failure"] = True
    case["expected_alink_error"] = "BAD OBJECT"
    return case


