def _actc_presence_sprite_first_arg_result_case(
    input_module: str,
    input_arg: int | None,
    input_call: str,
    input_runtime_objects: list[str],
    expected_input_loads: list[str],
    unexpected_input_loads: list[str],
) -> dict[str, object]:
    return {
        "source": (
            "MODULE MAIN\r"
            "BYTE P\r"
            "PROC MAIN()\r"
            f"P={input_call}\r"
            "SpriteColor(P,1)\r"
            "RETURN\r"
        ),
        "has_stub": False,
        "runtime_library_objects": (
            input_runtime_objects + ["rt_sprite_color", "rt_sprite_on"]
        ),
        "expected_object_fragments": [
            f"u {input_module}\n",
            "u rt_sprite_color\n",
            *([] if input_arg is None else [f"i {input_arg}\n"]),
            "i 1\n",
            "v p 0\n",
        ],
        "expected_tail": _actc_input_result_first_arg_xa_runtime_tail(
            input_module, input_arg, "rt_sprite_color", 1, "sprite"
        ),
        "store_check_addr": 0xD027,
        "store_check_value": 0x01,
        "store_check_mask": 0x0F,
        "expected_alink_loads": [
            *expected_input_loads,
            "LIB/RT_SPRITE_COLOR.OBJ",
        ],
        "unexpected_alink_loads": [
            *unexpected_input_loads,
            "LIB/RT_SPRITE_ON.OBJ",
        ],
    }


