def _actc_mouse_button_sid_byte_pair_result_case(
    button_module: str,
    button_call: str,
    sid_call: str,
    sid_module: str,
    literal_arg: int,
    arg_position: str,
) -> dict[str, object]:
    if arg_position not in {"first", "second"}:
        raise ValueError(f"unsupported SID byte-pair argument position: {arg_position}")
    helper_runtime_objects = {
        "rt_sid_wave": ["rt_sid_wave", "rt_sid_state", "rt_sid_vol"],
        "rt_sid_ad": ["rt_sid_ad", "rt_sid_sr", "rt_sid_wave"],
        "rt_sid_sr": ["rt_sid_sr", "rt_sid_ad", "rt_sid_wave"],
    }
    store_checks = {
        ("rt_sid_wave", "first"): {"store_check_addr": 0xD404, "store_check_value": 0x01, "store_check_mask": 0xFF},
        ("rt_sid_wave", "second"): {"store_check_addr": 0xD40B, "store_check_value": 0x00, "store_check_mask": 0xFF},
        ("rt_sid_ad", "first"): {"store_check_addr": 0xD405, "store_check_value": 0x97},
        ("rt_sid_ad", "second"): {"store_check_addr": 0xD40C, "store_check_value": 0x00},
        ("rt_sid_sr", "first"): {"store_check_addr": 0xD406, "store_check_value": 0xF8},
        ("rt_sid_sr", "second"): {"store_check_addr": 0xD40D, "store_check_value": 0x00},
    }
    if sid_module not in helper_runtime_objects:
        raise ValueError(f"unsupported SID byte-pair helper: {sid_module}")
    source_call = (
        f"{sid_call}(B,{literal_arg})\r"
        if arg_position == "first"
        else f"{sid_call}({literal_arg},B)\r"
    )
    expected_tail = (
        _actc_input_result_first_arg_ay_runtime_tail(
            button_module, None, sid_module, literal_arg, "SID"
        )
        if arg_position == "first"
        else _actc_input_result_second_arg_ay_runtime_tail(
            button_module, None, sid_module, literal_arg, "SID"
        )
    )
    sid_expected_loads = (
        ["LIB/RT_SID_WAVE.OBJ", "LIB/RT_SID_STATE.OBJ"]
        if sid_module == "rt_sid_wave"
        else [f"LIB/{sid_module.upper()}.OBJ"]
    )
    button_expected_loads = [
        f"LIB/{button_module.upper()}.OBJ",
        "LIB/RT_MB.OBJ",
        "LIB/RT_MS.OBJ",
    ]
    unexpected_sid_loads = [
        f"LIB/{module.upper()}.OBJ"
        for module in helper_runtime_objects[sid_module]
        if module != sid_module and not (sid_module == "rt_sid_wave" and module == "rt_sid_state")
    ]
    other_button = "rt_mb2" if button_module == "rt_mb1" else "rt_mb1"
    return {
        "source": (
            "MODULE MAIN\r"
            "BYTE B\r"
            "PROC MAIN()\r"
            f"B={button_call}()\r"
            + source_call
            + "RETURN\r"
        ),
        "has_stub": False,
        "runtime_library_objects": (
            _MOUSE_BUTTON_RUNTIME_OBJECTS[button_module]
            + helper_runtime_objects[sid_module]
        ),
        "expected_object_fragments": [
            f"u {button_module}\n",
            f"u {sid_module}\n",
            f"i {literal_arg}\n",
            "v b 0\n",
        ],
        "expected_tail": expected_tail,
        "expected_alink_loads": button_expected_loads + sid_expected_loads,
        "unexpected_alink_loads": [
            f"LIB/{other_button.upper()}.OBJ",
            *unexpected_sid_loads,
            "LIB/RT_MP.OBJ",
            "LIB/RT_MSEEN.OBJ",
            "LIB/RT_MX.OBJ",
            "LIB/RT_MY.OBJ",
            "LIB/RT_JOY.OBJ",
        ],
        **store_checks[(sid_module, arg_position)],
    }


