def _refresh_seeded_runtime_expected_tails() -> None:
    for case in DIRECT_PRG_CASES.values():
        seed_object = case.get("seed_object")
        runtime_modules = case.get("runtime_library_objects")
        if (
            not isinstance(seed_object, str)
            or not isinstance(runtime_modules, list)
            or not runtime_modules
            or "\nm " not in "\n" + seed_object
        ):
            continue
        imports = _obj_imports(seed_object)
        if not imports or any(
            not (UDOS_RUNTIME_MODULES / f"{name}.obj").is_file()
            for name in imports
        ):
            continue
        case["expected_tail"] = _linked_seed_runtime_tail(seed_object)


RUNTIME_SEEDED_MACHINE_SHAPES: list[str] = []


def _native_runtime_seed_from_expected_tail(
    shape: str, seed_object: str, expected_tail: bytes
) -> str:
    imports = _obj_imports(seed_object)
    modules = _runtime_module_closure(imports)
    runtime_size = sum(len(_runtime_obj_machine_code(module)) for module in modules)
    root_size = len(expected_tail) - runtime_size
    if root_size <= 0:
        raise RuntimeError(f"seeded runtime root has invalid size for {shape}: {root_size}")

    exports = _obj_exports(seed_object, f"legacy seeded runtime object {shape}")
    if exports != {"main": 0}:
        raise RuntimeError(f"seeded runtime object has unsupported exports for {shape}: {exports}")

    legacy_calls = [
        _object_selector_index(match.group(1))
        for line in seed_object.splitlines()
        if line.startswith("b ")
        for match in re.finditer(r"u([0-9A-Z])", line)
    ]
    code = bytearray(expected_tail[:root_size])
    called_modules: list[str] = []
    for import_index in legacy_calls:
        module = imports[import_index]
        if module not in called_modules:
            called_modules.append(module)
    module_orders = [modules, _runtime_module_closure(called_modules)]
    relocs: list[tuple[int, int]] | None = None
    for module_order in module_orders:
        module_addrs = _runtime_module_addrs(
            module_order, DIRECT_PRG_LOAD_ADDR + root_size
        )
        address_to_import = {
            module_addrs[module]: index for index, module in enumerate(imports)
        }
        candidate: list[tuple[int, int]] = []
        for offset in range(1, len(code) - 1):
            if code[offset - 1] != 0x20:
                continue
            target = code[offset] | (code[offset + 1] << 8)
            if target in address_to_import:
                candidate.append((offset, address_to_import[target]))
        if [import_index for _offset, import_index in candidate] == legacy_calls:
            relocs = candidate
            break

    if relocs is None:
        raise RuntimeError(
            f"seeded runtime call order mismatch for {shape}: "
            f"legacy={legacy_calls}"
        )
    native_calls = [import_index for _offset, import_index in relocs]

    selector_chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if len(imports) > len(selector_chars):
        raise RuntimeError(f"too many seeded runtime imports for {shape}: {len(imports)}")
    for offset, _import_index in relocs:
        code[offset] = 0
        code[offset + 1] = 0

    native_seed = (
        "OBJ1\n"
        f"x main 0 {len(code)}\n"
        "b "
        + "".join(f"u{selector_chars[index]}" for index in native_calls)
        + "M\n"
        + "m "
        + " ".join(f"{byte:02X}" for byte in code)
        + "\n"
        + "".join(
            f"r {offset} u{selector_chars[import_index]}\n"
            for offset, import_index in relocs
        )
        + "".join(f"u {module}\n" for module in imports)
        + "n main\n"
    )
    return native_seed


def _promote_seeded_runtime_objects() -> None:
    promoted: list[str] = []
    for shape, case in DIRECT_PRG_CASES.items():
        seed_object = case.get("seed_object")
        runtime_modules = case.get("runtime_library_objects")
        expected_tail = case.get("expected_tail")
        if (
            not isinstance(seed_object, str)
            or not isinstance(runtime_modules, list)
            or not runtime_modules
            or not isinstance(expected_tail, bytes)
            or "\nm " in "\n" + seed_object
            or bool(case.get("expect_alink_failure", False))
        ):
            continue
        case["seed_object"] = _native_runtime_seed_from_expected_tail(
            shape, seed_object, expected_tail
        )
        case["expected_tail"] = _linked_seed_runtime_tail(str(case["seed_object"]))
        promoted.append(shape)

    if len(promoted) != 102:
        raise RuntimeError(
            f"expected 102 seeded runtime objects, promoted {len(promoted)}"
        )
    RUNTIME_SEEDED_MACHINE_SHAPES.extend(promoted)


_REAL_SPECIAL_IMPORTERS = {
    "rt_f_add",
    "rt_f_sub",
    "rt_f_addsub_core",
    "rt_f_mul",
    "rt_f_div",
    "rt_f_cmp",
    "rt_f_sqrt",
}


def _complete_runtime_library_dependencies() -> None:
    for case in DIRECT_PRG_CASES.values():
        modules = case.get("runtime_library_objects")
        if not isinstance(modules, list) or not _REAL_SPECIAL_IMPORTERS.intersection(
            modules
        ):
            continue

        # Stage the dependency for every REAL-library fixture, including cases
        # where the arithmetic objects are intentional dead-strip decoys.
        if "rt_f_special" not in modules:
            modules.append("rt_f_special")

        expected_loads = case.get("expected_alink_loads")
        selected = isinstance(expected_loads, list) and any(
            f"LIB/{module.upper()}.OBJ" in expected_loads
            for module in _REAL_SPECIAL_IMPORTERS
        )
        special_load = "LIB/RT_F_SPECIAL.OBJ"
        if selected and isinstance(expected_loads, list):
            if special_load not in expected_loads:
                expected_loads.append(special_load)
            unexpected_loads = case.get("unexpected_alink_loads")
            if isinstance(unexpected_loads, list) and special_load in unexpected_loads:
                unexpected_loads.remove(special_load)
            continue

        unexpected_loads = case.get("unexpected_alink_loads")
        if isinstance(unexpected_loads, list) and special_load not in unexpected_loads:
            unexpected_loads.append(special_load)


_complete_runtime_library_dependencies()
_promote_seeded_runtime_objects()
_refresh_seeded_runtime_expected_tails()


